package main
import "std/map"
import "std/set"
import "std/io"

func put[K Ord, V](m Map[K, V], k K, v V) Map[K, V] { map.mapInsert(m, k, v) }
type Desc = Desc(Int) deriving Eq
instance Ord[Desc] { compare(a, b) { match (a, b) { (Desc(x), Desc(y)) => compare(y, x) } } }
func verify(name String, ok Bool) IO[Unit] { if ok { println(name) } else { io.ioFail(name) } }
func main() IO[Unit] {
  let original = put(put(map.emptyMap(), 3, "c"), -1, "a")
  let replaced = put(original, 3, "new")
  let reversed = map.mapFromListBy([(1, "a"), (3, "c"), (2, "b")], func(a, b) => compare(b, a))
  let custom = put(put(map.emptyMap(), Desc(1), "a"), Desc(3), "c")
  let strings = put(put(put(map.emptyMap(), "日", 1), "a", 2), "é", 3)
  let direct = map.mapFromListBy([(2, "b"), (1, "a")], compare)
  do {
    verify("generic native Int", map.mapKeys(original) == [-1, 3])
    verify("persistent replacement", map.mapLookup(original, 3) == Some("c") && map.mapLookup(replaced, 3) == Some("new"))
    verify("generic native String", map.mapKeys(strings) == ["a", "é", "日"])
    verify("reversed primitive comparator", map.mapKeys(reversed) == [3, 2, 1])
    verify("custom Ord dictionary", map.mapKeys(custom) == [Desc(3), Desc(1)])
    verify("direct compare witness", map.mapKeys(direct) == [1, 2])
    verify("native set ordering", set.setToList(set.setFromList([3, -1, 3, 2])) == [-1, 2, 3])
  }
}
